var EXTRA=[{"dot": "gray", "j": "Arthrosc Tech", "h": "Radice meniscale più osteotomia tibiale alta: pianificazione e guide su misura", "v": "Nota tecnica iraniana su due tue procedure insieme, tunnel transtibiale e osteotomia, con pianificazione TC e guide stampate; nessun esito clinico.", "pmid": "42889858", "doi": "10.1002/atn2.70323", "temi": ["radice meniscale", "osteotomia tibiale alta", "guide stampate", "pianificazione"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Avulsione dell'eminenza tibiale: fissazione artroscopica con compressione circonferenziale", "v": "Nota tecnica indiana su una lesione rara; descrive la procedura, nessun dato su pazienti o esiti nell'abstract.", "pmid": "42890472", "doi": "10.1002/atn2.70311", "temi": ["LCA", "avulsione", "eminenza tibiale", "tecnica artroscopica"]}, {"dot": "gray", "j": "JBI Evid Synth", "h": "Chinesiofobia dopo il LCA: mappa di una letteratura frammentata", "v": "Revisione di scoping: pochi studi di intervento, adolescenti e donne poco rappresentati; è una mappa, non una stima di effetto.", "pmid": "42873955", "doi": "10.11124/JBIES-26-00001", "temi": ["LCA", "chinesiofobia", "riabilitazione", "rientro allo sport"]}, {"dot": "gray", "j": "Diagnostics (Basel)", "h": "Asse della gamba e orientamento della caviglia: cambiamenti dopo osteotomia, in modo esplorativo", "v": "Radiografie in carico di una coorte retrospettiva; il sottogruppo operato è piccolo e confuso da procedure diverse, nessun esito clinico.", "pmid": "42882320", "doi": "10.3390/diagnostics16193165", "temi": ["osteotomia", "allineamento", "radiografia in carico", "caviglia"]}, {"dot": "gray", "j": "Curr Rev Musculoskelet Med", "h": "Stato dell'arte sul LCA: innesto, plastica laterale, criteri di rientro", "v": "Revisione narrativa, non uno studio: sostiene che la plastica laterale vada riservata ai ginocchi ad alto rischio e che il limb symmetry index possa sovrastimare il recupero; nessun dato nuovo, e va contro la tua scelta di farla sempre.", "pmid": "42873380", "doi": "10.1007/s12178-026-10060-9", "temi": ["LCA", "plastica laterale", "tendine quadricipitale", "rientro allo sport"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Menisco laterale ipermobile: ripararlo, non asportarlo", "v": "Editoriale di commento del gruppo LaPrade: l'obiettivo è la riparazione anatomica senza sovra-vincolare lo iato popliteo; è un'opinione di esperti, non un dato.", "pmid": "42859895", "doi": "10.1002/arj.70655", "temi": ["menisco laterale", "riparazione meniscale", "iato popliteo", "LaPrade"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Tecnica Sonnery-Cottet: passaggio atraumatico dell'innesto anterolaterale", "v": "Nota tecnica giapponese con un passafilo e un porta-nodi per i due tunnel tibiali; descrive la procedura, nessun dato su pazienti o esiti.", "pmid": "42852393", "doi": "10.1002/atn2.70305", "temi": ["legamento anterolaterale", "Sonnery-Cottet", "tunnel tibiali", "tecnica"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Manico di secchio del corno anteriore: sutura all-inside con nodo artroscopico", "v": "Nota tecnica che evita l'incisione cutanea della sutura inside-out o outside-in; nessun dato su pazienti o esiti nell'abstract.", "pmid": "42836072", "doi": "10.1002/atn2.70267", "temi": ["menisco mediale", "manico di secchio", "sutura all-inside", "corno anteriore"]}, {"dot": "gray", "j": "Int J Sports Phys Ther", "h": "Qualità del movimento dopo LCA nei giovani: uno schema per riabilitazione e rientro", "v": "Commento clinico (livello 5) su strumenti qualitativi per compiti su una e due gambe e cambi di direzione negli adolescenti; opinione strutturata, non uno studio.", "pmid": "42893141", "doi": "10.26603/001c.169922", "temi": ["LCA adolescenti", "qualità del movimento", "rientro allo sport", "riabilitazione"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Radice mediale transtibiale: cross-bar semplificato e centralizzazione senza nodi", "v": "Nota tecnica con video sul tuo stesso accesso transtibiale; aggiunge la centralizzazione contro l'estrusione, nessun esito clinico.", "pmid": "42871408", "doi": "10.1002/atn2.70324", "temi": ["radice meniscale", "transtibiale", "centralizzazione", "estrusione"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Menisco discoide laterale tipo Wrisberg: ancora senza nodi che risparmia la fisi", "v": "Nota tecnica su un caso instabile in un paziente in crescita; evita il tunnel transtibiale vicino alla cartilagine di crescita, nessun esito clinico.", "pmid": "42894727", "doi": "10.1002/atn2.70319", "temi": ["menisco discoide", "fisi aperta", "ancora senza nodi", "radice posteriore"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Artrosi femororotulea: non controindica l'osteotomia tibiale alta di apertura", "v": "Commento editoriale di un chirurgo di Singapore sul movimento della rotula nel piano coronale; è opinione, non uno studio nuovo.", "pmid": "42837200", "doi": "10.1002/arj.70664", "temi": ["osteotomia tibiale alta", "femororotulea", "artrosi", "rotula"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Instabilità rotulea: meglio la TT-TG, ma l'origine della deviazione decide", "v": "Editoriale di Dejour e Mazy (Lione): un valore elevato non porta in automatico a osteotomia della tuberosità, va cercata l'origine; opinione, non dati.", "pmid": "42832267", "doi": "10.1002/arj.70656", "temi": ["instabilità rotulea", "TT-TG", "tuberosità tibiale", "trocleoplastica"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Tendine peroneo lungo per il LCA: la funzione della caviglia non peggiora", "v": "Serie retrospettiva indiana che confronta la caviglia prima e dopo, in pazienti poco attivi; non è il tuo innesto e non dice nulla sulla stabilità del ginocchio.", "pmid": "42894519", "doi": "10.1007/s43465-026-01884-1", "temi": ["LCA", "peroneo lungo", "prelievo", "caviglia"]}, {"dot": "gray", "j": "Arch Orthop Trauma Surg", "h": "LCA: verifica del tunnel tibiale con il notch come riferimento, validata in 3D", "v": "Studio di validazione retrospettivo su ricostruzioni all-inside; misura dove cade il tunnel, non gli esiti clinici.", "pmid": "42867698", "doi": "10.1007/s00402-026-06442-w", "temi": ["LCA", "tunnel tibiale", "posizione", "imaging 3D"]}];
var SCOPERTE=[{"t": "Legamento artificiale a doppio fascio senza conflitto: dalla Cina un LCA confrontato con il fascio singolo", "v": "Studio retrospettivo di Shenzhen su 45 pazienti: ricostruzione con legamento artificiale a doppio fascio «senza conflitto in quattro dimensioni» contro fascio singolo over-the-top, follow-up di pochi mesi e gruppi sbilanciati. Vale la deviazione perché è un approccio e un materiale che in Occidente quasi non si vedono; pochi pazienti e breve controllo, nessuna prova di vantaggio.", "pmid": "42896996", "doi": "10.7507/1002-1892.202603058", "temi": ["legamento artificiale", "doppio fascio", "LCA", "Cina"]}, {"t": "Il crociato anteriore si dirama nella cartilagine fino all'osso: una microscopia dal Giappone", "v": "Microscopia ottica ed elettronica su legamenti di sette persone (Oita): le fibre del LCA si ramificano nella cartilagine e raggiungono la tibia, cosa che spiega l'inserzione. Vale la deviazione perché è anatomia dell'attacco su cui poggiano i tunnel; osservazione descrittiva su pochissimi campioni, nessun esito clinico.", "pmid": "42895845", "doi": "10.1093/jmicro/dfag036", "temi": ["anatomia del LCA", "inserzione tibiale", "microscopia", "Giappone"]}, {"t": "Linee guida taiwanesi per l'ecografia del ginocchio: dalla diagnosi all'infiltrazione guidata", "v": "Guida standardizzata degli ecografisti muscolo-scheletrici di Taiwan (cornice EURO-MUSCULUS/USPRM) per compartimenti del ginocchio, menischi, collaterali e infiltrazioni sotto guida. Vale la deviazione perché mostra come l'ecografia diventa primo livello altrove; è una revisione didattica, non una prova di accuratezza.", "pmid": "42891407", "doi": "10.4103/jmu.JMU-D-26-00013", "temi": ["ecografia", "ginocchio", "Taiwan", "diagnosi"]}];
var SOC={"1": {"video": "Quando si cuce il menisco insieme al crociato, conta come si dispongono i punti? Uno studio retrospettivo di Zhejiang su 186 pazienti, pubblicato su Indian Journal of Orthopaedics, ha seguito le riparazioni per circa due anni. La sutura ha ceduto nell'11,8% dei casi; con i punti solo orizzontali nel 17,2%, con punti verticali e orizzontali insieme nel 7,8%.\n\nTra i fattori associati al fallimento ci sono i soli punti orizzontali e il menisco interno. Fra punti verticali e combinati la differenza non è chiara: l'intervallo di confidenza è molto largo, da 0,64 a 3,79.\n\nÈ uno studio retrospettivo e i punti li sceglieva il chirurgo. Mostra un'associazione, non una causa, e il crociato era sempre ricostruito con i tendini della coscia.\nFonte: PubMed, PMID 42894623.", "linkedin": "Menisco cucito insieme al crociato, conta la disposizione dei punti? Studio retrospettivo di Zhejiang su 186 operati (Indian Journal of Orthopaedics, 2026). La sutura ha ceduto nell'11,8%; con punti solo orizzontali nel 17,2%, con punti verticali e orizzontali insieme nel 7,8%.\n\nAnche il menisco interno ha ceduto più spesso dell'esterno. Fra punti verticali e combinati la differenza non è chiara.\n\nIl limite: retrospettivo, punti scelti dal chirurgo; un'associazione e non una causa.\nFonte: PubMed, PMID 42894623.", "instagram": "Menisco e crociato insieme\n\nPunti solo orizzontali, la sutura cede nel 17,2%; punti combinati nel 7,8%. Il menisco interno cede più spesso.\n\nStudio retrospettivo: un legame, non una causa.\nFonte: PubMed, PMID 42894623.", "pazienti": "Menisco e crociato operati insieme: il modo di disporre i punti di sutura potrebbe contare. In uno studio su 186 persone (Indian Journal of Orthopaedics, 2026) circa 12 suture del menisco su 100 hanno richiesto un nuovo intervento.\n\nPiù spesso con i punti in un solo modo (circa 17 su 100) che combinando due modi (circa 8 su 100). Il menisco interno ha ceduto più spesso dell'esterno.\n\nStudio retrospettivo: indica un legame, non una causa. La scelta si discute con il chirurgo.\nFonte: PubMed, PMID 42894623."}};
var SOCV={"1": {"video": {"chir": ["Sutura del corno posteriore durante la ricostruzione del LCA, quale configurazione dei punti? Coorte retrospettiva di Zhejiang, 186 pazienti, sutura all-inside, innesto hamstring, follow-up medio 28 mesi, su Indian Journal of Orthopaedics. Fallimento complessivo dell'11,8%; orizzontale 17,2%, verticale 10,9%, combinata 7,8%, p=0,024.", "Sopravvivenza a 24 mesi 92,2% con la combinata (IC 95% 85,7-98,7) contro 82,8% con l'orizzontale (IC 95% 73,1-92,5). Nel modello aggiustato l'orizzontale ha HR 2,84 (IC 95% 1,32-6,14) e il menisco mediale HR 2,42 (IC 95% 1,18-4,96). Verticale contro combinata: HR 1,56 (IC 95% 0,64-3,79), non distinguibili.", "Limiti: retrospettivo, configurazione scelta dal chirurgo, innesto sempre hamstring, un solo dispositivo. Il confronto grezzo orizzontale contro combinata ha RR 2,21 (IC 95% 0,80-6,08). Ipotesi da verificare in uno studio randomizzato.\nFonte: PubMed, PMID 42894623."], "misto": ["Quando si cuce il menisco insieme al crociato, conta come si dispongono i punti? Uno studio retrospettivo di Zhejiang su 186 pazienti, pubblicato su Indian Journal of Orthopaedics, ha seguito le riparazioni per circa due anni. La sutura ha ceduto nell'11,8% dei casi; con i punti solo orizzontali nel 17,2%, con punti verticali e orizzontali insieme nel 7,8%.", "Tra i fattori associati al fallimento ci sono i soli punti orizzontali e il menisco interno. Fra punti verticali e combinati la differenza non è chiara: l'intervallo di confidenza è molto largo, da 0,64 a 3,79.", "È uno studio retrospettivo e i punti li sceglieva il chirurgo. Mostra un'associazione, non una causa, e il crociato era sempre ricostruito con i tendini della coscia.\nFonte: PubMed, PMID 42894623."], "pazienti": ["Quando si ripara il menisco durante l'operazione al legamento crociato, ci sono diversi modi di disporre i punti. Uno studio su 186 persone ha visto che la riparazione ha richiesto un nuovo intervento in circa 12 casi su 100.", "Era più frequente con i punti posti in un solo modo (orizzontale), circa 17 su 100, che combinando due modi, circa 8 su 100. Il menisco interno ha ceduto più spesso dell'esterno.", "Lo studio guarda al passato e non prova una causa. La scelta dei punti spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42894623."]}, "linkedin": {"chir": ["Sutura del corno posteriore con LCA, configurazione dei punti (Indian J Orthop, 2026). Coorte retrospettiva, 186 pazienti, all-inside, hamstring, follow-up medio 28,4 mesi; fallimento 11,8%, orizzontale 17,2%, verticale 10,9%, combinata 7,8% (p=0,024).", "HR aggiustato per la sola configurazione orizzontale 2,84 (IC 95% 1,32-6,14); menisco mediale 2,42 (IC 95% 1,18-4,96); verticale contro combinata 1,56 (IC 95% 0,64-3,79).", "Limiti: retrospettivo, scelta del chirurgo, solo hamstring; il vantaggio della combinata sulla verticale non è dimostrato.\nFonte: PubMed, PMID 42894623."], "misto": ["Menisco cucito insieme al crociato, conta la disposizione dei punti? Studio retrospettivo di Zhejiang su 186 operati (Indian Journal of Orthopaedics, 2026). La sutura ha ceduto nell'11,8%; con punti solo orizzontali nel 17,2%, con punti verticali e orizzontali insieme nel 7,8%.", "Anche il menisco interno ha ceduto più spesso dell'esterno. Fra punti verticali e combinati la differenza non è chiara.", "Il limite: retrospettivo, punti scelti dal chirurgo; un'associazione e non una causa.\nFonte: PubMed, PMID 42894623."], "pazienti": ["Menisco e crociato operati insieme: il modo di disporre i punti di sutura potrebbe contare. In uno studio su 186 persone (Indian Journal of Orthopaedics, 2026) circa 12 suture del menisco su 100 hanno richiesto un nuovo intervento.", "Più spesso con i punti in un solo modo (circa 17 su 100) che combinando due modi (circa 8 su 100). Il menisco interno ha ceduto più spesso dell'esterno.", "Studio retrospettivo: indica un legame, non una causa. La scelta si discute con il chirurgo.\nFonte: PubMed, PMID 42894623."]}, "instagram": {"chir": ["Sutura meniscale e LCA", "Orizzontale sola: fallimento 17,2% contro 7,8% con la combinata (p=0,024); HR 2,84 (IC 95% 1,32-6,14).", "Retrospettivo, hamstring, scelta del chirurgo.\nFonte: PubMed, PMID 42894623."], "misto": ["Menisco e crociato insieme", "Punti solo orizzontali, la sutura cede nel 17,2%; punti combinati nel 7,8%. Il menisco interno cede più spesso.", "Studio retrospettivo: un legame, non una causa.\nFonte: PubMed, PMID 42894623."], "pazienti": ["Menisco cucito, conta come?", "Con i punti in un solo modo servono più spesso nuovi interventi (circa 17 su 100 contro circa 8 su 100 con due modi).", "Lo studio guarda al passato. Se ne parla con il chirurgo.\nFonte: PubMed, PMID 42894623."]}, "reel": {"chir": ["LCA e sutura del corno posteriore", "Orizzontale 17,2% contro combinata 7,8%.", "Retrospettivo.\nFonte: PubMed, PMID 42894623."], "misto": ["Menisco cucito col crociato", "Punti solo orizzontali, più cedimenti (17,2% contro 7,8%).", "Un legame, non una causa.\nFonte: PubMed, PMID 42894623."], "pazienti": ["Menisco cucito, conta come?", "Punti in un solo modo, più nuovi interventi (circa 17 su 100 contro 8 su 100).", "Se ne parla con il chirurgo.\nFonte: PubMed, PMID 42894623."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Ginocchio #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #menisco #legamentocrociato #chirurgiadelginocchio #medicinadellosport #riabilitazione #ortopediaticino #ticino #medicinabasatasulleprove #salute", "kw": "sutura del menisco, legamento crociato anteriore, menisco, riparazione meniscale, ginocchio"}};
var NLB={"1": {"prof": ["Sutura del corno posteriore con LCA: la configurazione orizzontale sola si associa a più fallimenti", "Coorte retrospettiva di Zhejiang (Indian J Orthop, 2026; 186 LCA con sutura all-inside del corno posteriore, hamstring, follow-up medio 28,4 mesi): fallimento 11,8%; orizzontale 17,2%, verticale 10,9%, combinata 7,8% (p=0,024). Orizzontale HR 2,84 (IC 95% 1,32-6,14) e menisco mediale HR 2,42 (IC 95% 1,18-4,96) sono fattori indipendenti.", "Nota critica: configurazione scelta dal chirurgo, verticale e combinata non distinguibili (HR 1,56; IC 95% 0,64-3,79), innesto sempre hamstring."], "mix": ["Menisco e crociato operati insieme: la disposizione dei punti può contare", "In uno studio retrospettivo cinese su 186 operati di legamento crociato anteriore con sutura del corno posteriore del menisco, la riparazione è fallita nell'11,8% dei casi: più spesso con i punti solo orizzontali (17,2%) che combinando punti verticali e orizzontali (7,8%). Anche il menisco interno ha ceduto più spesso dell'esterno.", "Nota sul limite: i punti li sceglieva il chirurgo caso per caso e fra punti verticali e combinati la differenza non è chiara; servono studi randomizzati."], "paz": ["Menisco e crociato operati insieme: lo schema dei punti di sutura può avere un ruolo", "In uno studio su 186 persone operate al legamento crociato anteriore con sutura del menisco, circa 12 suture su 100 hanno poi richiesto un nuovo intervento: circa 17 su 100 con i punti posti in un solo modo (orizzontale) e circa 8 su 100 combinando due modi. Il menisco interno ha ceduto più spesso dell'esterno.", "Lo studio guarda al passato e non prova una causa: la scelta della sutura è del chirurgo, caso per caso."], "kw": "sutura del menisco, legamento crociato anteriore, riparazione meniscale, ginocchio"}, "2": {"prof": ["MPFL: quadricipite e hamstring non si distinguono nei punteggi (4 studi, 246 pazienti)", "Metanalisi (Indian J Orthop, 2026; 4 studi comparativi, 246 pazienti): nessuna differenza significativa in Kujala, Lysholm, Tegner e VAS, nessuna lussazione ricorrente; indice di simmetria della forza più alto con il quadricipite in un solo studio. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.", "Nota critica: pochi studi retrospettivi, nessuna lussazione non è prova di equivalenza, forza misurata in uno studio."], "mix": ["Ricostruzione del legamento della rotula: tendine del quadricipite o ischiocrurali, esiti simili", "In una revisione di quattro studi su 246 pazienti operati per instabilità della rotula, usare il tendine del quadricipite o i tendini ischiocrurali per ricostruire il legamento che trattiene la rotula (MPFL) ha dato punteggi e dolore senza differenze significative, e nessuna lussazione ricorrente nei due gruppi.", "Nota sul limite: pochi studi, tutti retrospettivi; l'assenza di nuove lussazioni va letta con cautela."], "paz": ["Instabilità della rotula: due tendini diversi per ricostruire il legamento, risultati simili", "Quando la rotula tende a uscire dalla sua sede, il legamento che la trattiene si può ricostruire con un tendine preso dalla coscia davanti (quadricipite) o dietro (ischiocrurali). In una revisione di quattro studi su 246 persone i risultati riferiti e il dolore non erano diversi e nessuno ha avuto una nuova lussazione.", "Gli studi sono pochi e guardano al passato: la scelta del tendine si discute con il chirurgo."], "kw": "instabilità della rotula, legamento patello-femorale mediale, tendine del quadricipite, ginocchio"}, "3": {"prof": ["LCA precoce o tardivo: in cinque casistiche il ritardo si associa a più meniscectomie e protesi", "Revisione sistematica (Ir J Med Sci, 2026; 5 studi, 1659 pazienti, follow-up 5-17,5 anni): incidenza di artrosi dal 2% al 49% con metodi diversi; nella ricostruzione tardiva più lesioni meniscali secondarie, meniscectomie e protesi totali (10,9% contro fino a 0,2% nella precoce). Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.", "Nota critica: definizioni di precoce e tardivo diverse fra gli studi, nessuna stima aggregata, coorti non randomizzate."], "mix": ["Crociato operato presto o tardi: il ritardo si associa a più danni al menisco", "Una revisione di cinque studi su 1659 pazienti ha confrontato la ricostruzione del legamento crociato anteriore eseguita presto o tardi. Con l'intervento tardivo risultavano più lesioni secondarie del menisco, più asportazioni del menisco e più protesi di ginocchio (10,9% contro fino allo 0,2%), ma gli studi definiscono «presto» e «tardi» in modo diverso.", "Nota sul limite: il legame non prova una causa e i dati sull'artrosi sono troppo diversi fra loro per concludere."], "paz": ["Legamento crociato: operarsi presto o tardi può cambiare il rischio per il menisco", "In una revisione di cinque studi su 1659 persone, chi è stato operato più tardi al legamento crociato aveva più spesso lesioni del menisco e, a distanza di anni, più protesi di ginocchio. Gli studi non definiscono «presto» e «tardi» allo stesso modo.", "Il legame non dimostra una causa: i tempi dell'intervento si decidono con il chirurgo."], "kw": "legamento crociato anteriore, tempi dell'intervento, menisco, artrosi del ginocchio"}, "4": {"prof": ["Sutura meniscale con coagulo di sangue o fibrina: guarigione dal 24% al 92%, prove deboli", "Revisione sistematica (Indian J Orthop, 2026; 7 studi, 237 menischi, 2 di livello II e 5 di livello IV): guarigione completa dal 24,1% al 91,7% secondo tipo di lesione, metodo e follow-up; fallimenti o reinterventi da 0 a 25%. Nei due studi di livello II la fibrina si associa a più guarigioni e meno fallimenti, senza significatività costante.", "Nota critica: cinque studi su sette sono serie di livello IV, sintesi solo descrittiva, nessun confronto adeguato con la sutura senza coagulo."], "mix": ["Sutura del menisco con coagulo di sangue o fibrina: i dati sono pochi e discordanti", "Una revisione di sette studi su 237 menischi cuciti con l'aggiunta di coagulo di sangue o fibrina riporta guarigioni molto diverse (dal 24% al 92% secondo il tipo di lesione e il metodo di controllo) e fallimenti fra lo 0 e il 25%. Nei due studi con un gruppo di confronto la fibrina è andata meglio, ma non sempre in modo significativo.", "Nota sul limite: la maggior parte degli studi è senza gruppo di confronto, per cui il vantaggio non è dimostrato."], "paz": ["Menisco cucito con aggiunta di coagulo: per ora i risultati sono incerti", "A volte, quando si cuce il menisco, si aggiunge un coagulo di sangue o di fibrina per aiutare la guarigione. Una revisione di sette studi su 237 menischi mostra risultati molto diversi da uno studio all'altro; negli studi che li riportano i punteggi riferiti sono migliorati rispetto a prima dell'intervento, con o senza coagulo.", "I dati sono ancora pochi: se ne parla con il chirurgo."], "kw": "sutura del menisco, coagulo di fibrina, guarigione del menisco, ginocchio"}, "5": {"prof": ["Protesi robotica: il consenso Asia-Pacifico dà 18 punti, il beneficio a lungo termine resta aperto", "Commento di un autore (Zhongguo Xiu Fu Chong Jian Wai Ke Za Zhi, ottobre 2026) al consenso della Arthroplasty Society in Asia sulla protesi robotica di anca e ginocchio, 18 affermazioni: nella TKA il robot migliora accuratezza di taglio, posizionamento e allineamento, mentre bersagli ottimali e beneficio clinico a lungo termine restano incerti; nella UKA riduce la variabilità tecnica, con segnali su funzione e revisione influenzati dalla selezione dei pazienti.", "Nota critica: interpretazione di un partecipante e non il consenso originale; opinione di esperti, nessun dato quantitativo nell'abstract."], "mix": ["Protesi con il robot: più precisione confermata, beneficio a lungo termine ancora da provare", "Un consenso di esperti asiatici sulla chirurgia robotica di anca e ginocchio, qui commentato da uno degli autori, afferma che il robot rende più preciso il posizionamento della protesi di ginocchio; non è però dimostrato quale allineamento sia il più adatto né se la maggiore precisione si traduca in un vantaggio duraturo per il paziente.", "Nota sul limite: è l'opinione di un gruppo di esperti, riassunta da uno dei partecipanti, non uno studio sui pazienti."], "paz": ["Protesi di ginocchio con il robot: più precisione, ma il vantaggio nel tempo non è provato", "Un gruppo di esperti asiatici ha messo per scritto che il robot aiuta il chirurgo a posizionare la protesi di ginocchio con più precisione. Non è però dimostrato che questo si traduca in un risultato diverso per il paziente negli anni.", "È un documento di opinione, non uno studio: i dettagli si discutono con il chirurgo."], "kw": "protesi di ginocchio robotica, chirurgia robotica, protesi monocompartimentale"}, "6": {"prof": ["UKA mediale, piatto mobile contro fisso: a 3 mesi punteggi simili, 64 pazienti, un chirurgo", "Studio retrospettivo (Front Surg, 2026; Shaoxing; 64 UKA mediali, 32 per gruppo): a 3 mesi VAS, HSS e KSS migliorano in entrambi senza differenze fra i gruppi; correzione dell'angolo femorotibiale −3,27° con il mobile contro −2,70° con il fisso (p<0,05) e maggiori guadagni di mobilità; nessuna infezione, mobilizzazione o lussazione del piatto. Il fisso costa meno in ricovero.", "Nota critica: follow-up di 3 mesi, retrospettivo, 32 per gruppo, nessun dato sulla sopravvivenza dell'impianto; deviazioni standard e intervalli non riportati nell'abstract."], "mix": ["Protesi monocompartimentale: piatto mobile o fisso, a 3 mesi risultati simili", "In uno studio su 64 persone operate di protesi monocompartimentale mediale (32 con piatto mobile, 32 con piatto fisso), dolore e funzione sono migliorati in modo simile dopo 3 mesi. Con il piatto mobile la correzione dell'allineamento e il recupero del movimento sono risultati un po' maggiori; con il fisso il costo del ricovero era minore.", "Nota sul limite: tre mesi sono pochi per giudicare una protesi e lo studio guarda al passato."], "paz": ["Protesi a metà ginocchio: piatto mobile o fisso, risultati simili dopo 3 mesi", "In uno studio su 64 persone con protesi a metà ginocchio (monocompartimentale), dolore e funzione sono migliorati in modo simile con il piatto mobile e con quello fisso nei primi 3 mesi. Nessuna infezione né mobilizzazione dell'impianto in questo periodo.", "Tre mesi sono un tempo breve: sulla scelta dell'impianto decide il chirurgo con il paziente."], "kw": "protesi monocompartimentale, protesi a metà ginocchio, artrosi del ginocchio"}, "7": {"prof": ["Allotrapianto osteocondrale: con aspirato di midollo osseo 2,4% di reinterventi contro 21,9%", "Revisione sistematica (Arthroscopy, 2026; 4 studi, 165 ginocchia, 3 di livello III e 1 di livello I; follow-up 5,5-18,0 mesi): in due studi comparativi reinterventi 2,4% con aspirato contro 21,9% senza; IKDC e KOOS JR senza differenze, MCID del KOOS JR raggiunta dall'88% contro il 55% (p=0,076); imaging discordante.", "Nota critica: solo due studi comparativi per l'esito principale, follow-up di mesi, conteggi assoluti non riportati nell'abstract."], "mix": ["Trapianto osteocondrale con midollo osseo aggiunto: meno reinterventi, ma pochi studi e tempo breve", "In una revisione di quattro studi su 165 ginocchia con difetti della cartilagine trattati con un trapianto da donatore, l'aggiunta di midollo osseo aspirato ha ridotto i nuovi interventi (2,4% contro 21,9% in due studi). Le immagini non sono concordi e i punteggi di funzione non sono risultati diversi.", "Nota sul limite: pochi studi, tempo di controllo di pochi mesi."], "paz": ["Cartilagine del ginocchio: trapianto da donatore con midollo osseo, meno nuovi interventi nei primi studi", "Per i difetti della cartilagine del ginocchio si può usare un trapianto da donatore. In quattro studi su 165 ginocchia, aggiungere midollo osseo prelevato dal paziente si è associato a meno nuovi interventi (2,4% contro 21,9% in due studi), ma i controlli durano pochi mesi e i punteggi di funzione non sono risultati diversi.", "I dati sono preliminari: se ne parla con il chirurgo."], "kw": "cartilagine del ginocchio, trapianto osteocondrale, midollo osseo"}, "8": {"prof": ["LCA con hamstring: disturbi del safeno 53,3% con semitendinoso e gracile contro 28,3%", "Studio prospettico osservazionale (SICOT J, 2026; Kozhikode; 120 pazienti, 60 per gruppo; controllo a 6 mesi): disturbi sensitivi nel territorio del safeno nel 28,3% (17/60) con il solo semitendinoso e nel 53,3% (32/60) con semitendinoso e gracile, differenza dichiarata significativa; per lo più senza ricadute sulle attività quotidiane. Valore di p e intervalli di confidenza non riportati nell'abstract.", "Nota critica: gruppi non randomizzati, sensibilità valutata a 6 mesi, innesto hamstring e non quadricipitale."], "mix": ["Crociato con tendini della coscia: più disturbi di sensibilità se si prelevano due tendini", "In uno studio su 120 pazienti operati di legamento crociato anteriore con tendini della parte posteriore della coscia, i disturbi di sensibilità lungo la gamba (nervo safeno) sono comparsi nel 28% dei pazienti con un solo tendine prelevato e nel 53% con due. Nella maggior parte dei casi non hanno disturbato le attività quotidiane.", "Nota sul limite: i due gruppi non erano scelti a caso e il controllo è a 6 mesi."], "paz": ["Crociato con tendini della coscia: più formicolio alla gamba se ne servono due", "Prelevare un tendine dalla coscia per ricostruire il legamento crociato può irritare un piccolo nervo (safeno) e dare formicolio o perdita di sensibilità lungo la gamba. In uno studio su 120 pazienti è successo a circa 28 su 100 con un tendine prelevato e a circa 53 su 100 con due, di solito senza ostacolare la vita quotidiana.", "Lo studio non prova una causa: la scelta del tendine si discute con il chirurgo."], "kw": "legamento crociato anteriore, tendini della coscia, nervo safeno, sensibilità"}, "9": {"prof": ["TKA robotica image-free: taglia del femore esatta nel 92% e della tibia nel 72%, su 100 pazienti", "Studio prospettico osservazionale (Indian J Orthop, 2026; Kolkata; 100 TKA consecutive, un'équipe): taglia femorale prevista esatta nel 92% (92/100) ed entro ±1 taglia nel 100%; tibiale esatta 72%, entro ±1 94%, entro ±2 100%, verificate con componenti di prova. Contro controlli storici di templating digitale p<0,0001 per il femore (esatta) e p=0,003 (±1). Intervalli di confidenza non riportati nell'abstract.", "Nota critica: controlli storici, una sola équipe, sistema non nominato nell'abstract, nessun esito clinico."], "mix": ["Protesi di ginocchio robotica: la taglia prevista dal sistema è esatta nel 92% dei femori", "In uno studio indiano su 100 protesi totali di ginocchio con un sistema robotico senza immagini preoperatorie, la misura del componente del femore prevista dal sistema è risultata esatta nel 92% dei casi e quella della tibia nel 72%, verificate con i componenti di prova in sala. Il confronto è con una serie storica di pianificazione digitale su immagini.", "Nota sul limite: il confronto è con controlli storici e lo studio non guarda gli esiti clinici."], "paz": ["Protesi di ginocchio con il robot: la misura dell'impianto prevista in sala è spesso esatta", "In uno studio su 100 persone con protesi totale di ginocchio impiantata con l'aiuto di un robot, la misura dell'impianto prevista dal sistema per il femore era quella giusta in 92 casi su 100, per la tibia in 72 su 100. È una misura tecnica e non un risultato di salute.", "Lo studio non misura come stanno i pazienti dopo: i dettagli si discutono con il chirurgo."], "kw": "protesi di ginocchio robotica, misura dell'impianto, chirurgia robotica"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Indian J Orthop",h:"Sutura del corno posteriore con LCA: la combinata verticale-orizzontale fallisce meno",v:"Coorte retrospettiva monocentrica (Zhejiang) su 186 LCA con sutura all-inside del corno posteriore, follow-up medio 28,4 mesi: fallimento della sutura 11,8% (22/186); orizzontale 17,2%, verticale 10,9%, combinata 7,8% (p=0,024). Sopravvivenza a 24 mesi 92,2% (IC 95% 85,7-98,7) con la combinata contro 82,8% (IC 95% 73,1-92,5) con l'orizzontale. Dopo aggiustamento l'orizzontale ha HR 2,84 (IC 95% 1,32-6,14) e il menisco mediale HR 2,42 (IC 95% 1,18-4,96).",ax:"Song, Cai, Qiu, Zhao, Song, Deng",date:"giu 2026",meta:"coorte retrospettiva comparativa, 186 pazienti (64 verticale, 58 orizzontale, 64 combinata), follow-up medio 28,4 mesi",pmid:'42894623',doi:'10.1007/s43465-026-01842-x',journal:"Indian journal of orthopaedics",authors:"Song Y, Cai K, Qiu J, Zhao M, Song Z, Deng H",design:"Studio retrospettivo comparativo monocentrico (centro accademico terziario; gennaio 2022-dicembre 2024): 214 cartelle riviste, 186 incluse (18-50 anni, LCA completa, sutura riparabile del corno posteriore in zona rosso-rosso o rosso-bianca, 10-40 mm; esclusi interventi precedenti, multilegamentose, condropatia III-IV, fumatori attivi). Tre gruppi per configurazione di sutura, scelta dal chirurgo (due operatori): verticale, orizzontale, combinata, tutte con il dispositivo all-inside FasT-Fix 360 (Smith & Nephew). LCA con hamstring quadruplicato in tutti, tunnel femorale dal portale anteromediale, fissazione sospesa con loop regolabile. Esito composito di fallimento (reintervento, o fallimento clinico con RM concordante), IKDC, Lysholm, Tegner, KT-1000, RM a 12 e 24 mesi con radiologo in cieco. Letto il testo completo (PMC).",pop:"186 pazienti, età 28,6 ± 7,4 anni, 68,8% uomini; menisco mediale 62,4% e laterale 37,6%; follow-up medio 28,4 ± 4,6 mesi (24-38). Plastica laterale non menzionata nel testo.",results:"Fallimento della sutura 11,8% (22/186); orizzontale 17,2% (10/58), verticale 10,9% (7/64), combinata 7,8% (5/64); p=0,024. Sopravvivenza libera da fallimento a 24 mesi 92,2% (IC 95% 85,7-98,7) combinata, 89,1% (IC 95% 81,5-96,7) verticale, 82,8% (IC 95% 73,1-92,5) orizzontale; log-rank p=0,024. Cox aggiustato: orizzontale HR 2,84 (IC 95% 1,32-6,14; p=0,008), menisco mediale HR 2,42 (IC 95% 1,18-4,96; p=0,014); verticale contro combinata HR 1,56 (IC 95% 0,64-3,79; p=0,328). A 24 mesi IKDC 87,6 ± 8,4 combinata, 82,4 ± 9,2 verticale, 79,8 ± 10,6 orizzontale; KT-1000 1,8 ± 0,9 mm contro 2,6 ± 1,2 mm con l'orizzontale (p=0,001); guarigione completa alla RM 78,1%, 67,2% e 56,9% (p=0,028). Tempo operatorio 68,4 minuti con la combinata contro 58,2 e 56,8.",concl:"Gli autori: la sutura combinata verticale-orizzontale si associa a risultati clinici migliori, maggiore stabilità e meno reinterventi, e va considerata nei casi adatti ma non imposta come regola, in attesa di studi randomizzati.",limits:"Retrospettivo: la configurazione era scelta dal chirurgo e qualità del tessuto e riducibilità non sono misurate con una scala, quindi il bias di selezione non è escluso · il vantaggio della combinata sulla verticale non è dimostrato (HR 1,56; IC 95% 0,64-3,79) e il confronto grezzo orizzontale contro combinata (10/58 contro 5/64) ha RR 2,21 con IC 95% 0,80-6,08 (potenza.py): la significatività poggia sul modello aggiustato · innesto sempre hamstring, un solo dispositivo, follow-up medio di 28 mesi · il comitato etico citato è quello del First People's Hospital of Yuhang District.",perte:"Verde: tocca due tuoi gesti, la sutura del menisco e il LCA, ma con un costrutto diverso. L'innesto è hamstring e non il tuo retto femorale o quadricipite, e la plastica laterale non è descritta: non direttamente trasferibile. Il dato utile è l'associazione della sola configurazione orizzontale e del menisco mediale con il fallimento. Non muove le tensioni. Cosa fare: nulla da cambiare nella tecnica; come ipotesi retrospettiva, nelle suture all-inside del corno posteriore mediale la sola configurazione orizzontale merita attenzione."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Indian J Orthop",h:"MPFL: quadricipite e hamstring non si distinguono nei punteggi, su quattro studi",v:"Metanalisi di 4 studi comparativi (246 pazienti) sulla ricostruzione isolata del MPFL: tendine quadricipitale contro hamstring senza differenze significative in Kujala, Lysholm, Tegner e dolore VAS; nessuna lussazione ricorrente in nessun gruppo; indice di simmetria della forza più alto con il quadricipite in un solo studio. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Thamrongskulsiri, Itthipanichpong, Limskul, Tanpowpong, Kuptniratsaikul",date:"lug 2026",meta:"revisione sistematica con metanalisi, 4 studi comparativi, 246 pazienti [PROSPERO CRD420261294759]",pmid:'42894633',doi:'10.1007/s43465-026-01898-9',journal:"Indian journal of orthopaedics",authors:"Thamrongskulsiri N, Itthipanichpong T, Limskul D, Tanpowpong T, Kuptniratsaikul S",design:"Revisione sistematica con metanalisi (PubMed, Scopus, Ovid MEDLINE) di studi comparativi tra autoinnesto di tendine quadricipitale e di hamstring per la ricostruzione isolata del MPFL. Esito primario: punteggio di Kujala; secondari: Lysholm, Tegner, dolore VAS, lussazione ricorrente, test di apprensione, forza. Modelli a effetti fissi o casuali secondo l'eterogeneità. Letto solo l'abstract (testo in PMC non aperto).",pop:"4 studi comparativi, 246 pazienti complessivi; età, displasia trocleare, altezza della rotula e tecnica di fissazione non riportate nell'abstract. Gli autori indicano che gli studi inclusi sono retrospettivi.",results:"Nessuna differenza statisticamente significativa tra quadricipite e hamstring in Kujala, Lysholm, Tegner e VAS; nessuna lussazione ricorrente in alcun gruppo; apprensione postoperatoria rara e simile. Forza riferita da un solo studio, con indice di simmetria dell'arto in estensione e flessione più alto nel gruppo quadricipite; rapporto ischiocrurali/quadricipite simile. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il quadricipite dà punteggi riferiti e stabilità comparabili all'hamstring nella ricostruzione del MPFL; l'assenza di lussazioni va letta con cautela per il campione piccolo e il disegno retrospettivo.",limits:"Quattro studi, 246 pazienti, retrospettivi: nessuna lussazione ricorrente non è prova di equivalenza di sicurezza · la forza è misurata in un solo studio · dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract · tecnica di prelievo e di fissazione non descritte · testo completo non letto.",perte:"Verde: tocca il tendine quadricipitale, il tuo innesto di elezione, ma applicato al MPFL e non al LCA con plastica laterale: non trasferibile alla tua ricostruzione del crociato. L'innesto che usi con le ancore FiberTak onlay non è specificato nel tuo profilo. Non muove le tensioni. Cosa fare: nulla da cambiare; il dato di parità è debole e retrospettivo."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Ir J Med Sci",h:"LCA tardivo: più meniscectomie e protesi in cinque casistiche, certezza limitata",v:"Revisione sistematica di 5 studi (RCT e coorti), 1659 pazienti, follow-up 5-17,5 anni, sul momento della ricostruzione del LCA: incidenza di artrosi dal 2% al 49% con metodi di misura diversi; la ricostruzione tardiva si associa a più lesioni meniscali secondarie e meniscectomie, e a più protesi totali (10,9% contro fino a 0,2% nella precoce). Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Visconti-Lopez, Aparcana-Granda, Mio-Rodriguez, Orihuela-Orrego, Quevedo, Hernández-Vásquez",date:"ott 2026",meta:"revisione sistematica PRISMA, 5 studi, 1659 pazienti, follow-up 5-17,5 anni",pmid:'42895623',doi:'10.1007/s11845-026-04650-2',journal:"Irish journal of medical science",authors:"Visconti-Lopez FJ, Aparcana-Granda DJ, Mio-Rodriguez EF, Orihuela-Orrego AF, Quevedo DAM, Hernández-Vásquez A",design:"Revisione sistematica PRISMA 2020 su PubMed, Cochrane Library, Embase, Web of Science e Scopus: RCT e coorti che confrontano l'incidenza di artrosi dopo ricostruzione precoce o tardiva del LCA. Qualità valutata con Newcastle-Ottawa e RoB 2. Definizioni di precoce e tardivo diverse fra gli studi. Letto solo l'abstract.",pop:"5 studi, 1659 pazienti; età, sesso, innesto e lesioni associate non riportati nell'abstract.",results:"Incidenza di artrosi dal 2% al 49% con valutazioni eterogenee (gradazione radiografica e punteggi riferiti). Ricostruzione tardiva associata a più lesioni meniscali secondarie e meniscectomie; protesi totali fino al 10,9% nei gruppi tardivi contro fino allo 0,2% nei precoci. Nessuna stima aggregata. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la ricostruzione precoce può associarsi a meno complicanze secondarie del ginocchio, in particolare meniscali, meniscectomie e protesi; l'eterogeneità delle definizioni, della misura dell'artrosi e del follow-up limita la certezza.",limits:"Cinque studi con definizioni diverse di precoce e tardivo · nessuna metanalisi, nessun intervallo di confidenza · coorti non randomizzate: il ritardo può dipendere dalla gravità o dal paziente · innesto e lesioni associate non descritti · testo completo non letto.",perte:"Verde: riguarda il LCA senza conflitto con la tua tecnica; l'innesto non è descritto, quindi nulla da dire sulla trasferibilità. Dato pratico: il ritardo si associa a più danno meniscale, come associazione e non come causa. Non muove le tensioni. Cosa fare: nulla da cambiare."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Indian J Orthop",h:"Sutura meniscale con coagulo di sangue o fibrina: guarigione molto variabile, prove deboli",v:"Revisione sistematica di 7 studi (2 di livello II, 5 di livello IV), 237 menischi riparati con coagulo di sangue o fibrina: guarigione completa dal 24,1% al 91,7% secondo tipo di lesione, metodo di valutazione e follow-up; fallimenti o reinterventi da 0 a 25%, più alti con lesioni degenerative a clivaggio orizzontale o complesse. Nei due studi di livello II la fibrina si associa a più guarigioni e a meno fallimenti, senza significatività costante. Intervalli di confidenza non riportati nell'abstract.",ax:"Thamrongskulsiri, Itthipanichpong, Limskul, Tanpowpong, Kuptniratsaikul",date:"giu 2026",meta:"revisione sistematica, 7 studi (2 livello II, 5 livello IV), 237 menischi, sintesi descrittiva",pmid:'42894585',doi:'10.1007/s43465-026-01866-3',journal:"Indian journal of orthopaedics",authors:"Thamrongskulsiri N, Itthipanichpong T, Limskul D, Tanpowpong T, Kuptniratsaikul S",design:"Revisione sistematica di studi clinici sulla riparazione del menisco con coagulo di sangue o fibrina, con confronto con la riparazione senza aumentazione quando disponibile; esiti: punteggi riferiti, guarigione strutturale, fallimenti o reinterventi. Sintesi descrittiva per eterogeneità. Letto solo l'abstract.",pop:"237 menischi riparati in 7 studi; età, sede e tipo di lesione per studio, tecnica di sutura e follow-up non riportati nell'abstract.",results:"Guarigione completa dal 24,1% al 91,7%; fallimenti o reinterventi da 0 a 25%. Nei due studi di livello II, fibrina con più guarigioni complete e fallimenti numericamente più bassi rispetto ai controlli, significatività non costante. Tutti gli studi che riportano punteggi mostrano miglioramento rispetto al basale, con o senza aumentazione. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: coagulo di sangue o fibrina si associa a guarigione favorevole ma eterogenea e a fallimenti in genere bassi; le prove sono limitate e incoerenti e servono studi di qualità per definirne il ruolo.",limits:"Cinque studi su sette sono serie di livello IV, senza confronto adeguato · sintesi solo descrittiva, nessuna stima aggregata · guarigione dal 24% al 92% secondo metodo e lesione: non confrontabile fra studi · testo completo non letto.",perte:"Verde: tocca la sutura meniscale che esegui. Non dice quali suture siano usate né se la tecnica coincida con la tua; l'aumentazione con coagulo non è una tua tecnica dichiarata. Non muove le tensioni. Cosa fare: nulla da cambiare; come informazione, le prove sull'aumentazione sono deboli."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Zhongguo Xiu Fu",h:"Protesi robotica, consenso Asia-Pacifico: più precisione, beneficio a lungo termine incerto",v:"Commento di un autore al consenso 2026 della Arthroplasty Society in Asia sulla protesi robotica di anca e ginocchio (18 affermazioni). Nella TKA il robot migliora accuratezza di taglio, posizionamento e allineamento e offre supporto quantitativo a allineamento individualizzato e bilanciamento; bersagli ottimali e beneficio clinico a lungo termine restano incerti. Nella UKA riduce la variabilità tecnica, con segnali su funzione e revisione influenzati da selezione dei pazienti e piattaforma.",ax:"Song, Xie, Yi, Li, Zhang, Nan, Chai",date:"ott 2026",meta:"consenso di esperti (commento di un partecipante), 18 affermazioni; opinione di esperti",pmid:'42896985',doi:'10.7507/1002-1892.202609030',journal:"Zhongguo xiu fu chong jian wai ke za zhi = Zhongguo xiufu chongjian waike zazhi = Chinese journal of reparative and reconstructive surgery",authors:"Song Y, Xie H, Yi J, Li H, Zhang Z, Nan S, Chai W",design:"Articolo di interpretazione, pubblicato con abstract in inglese su rivista cinese, delle raccomandazioni del consenso Asia-Pacifico (Arthroplasty Society in Asia, 2026) per TKA, THA e UKA robotiche; l'autore corrispondente ha partecipato a tutto il processo di formulazione. Letto solo l'abstract: le 18 affermazioni non sono state lette e il documento originale non è stato aperto.",pop:"Non applicabile (consenso di esperti): numero di esperti, metodo di consenso e livelli di accordo non riportati nell'abstract.",results:"Nessun dato quantitativo nell'abstract. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract. Per la TKA il robot migliora accuratezza di taglio, posizionamento e allineamento; per la THA posizionamento della coppa, lunghezza dell'arto e offset, senza riduzione dimostrata di lussazione o revisione; per la UKA minore variabilità tecnica.",concl:"Gli autori: serve chiarire quali pazienti traggano beneficio, quali bersagli di ricostruzione scegliere e se la precisione tecnica si traduca in valore clinico duraturo; sicurezza richiede formazione, capacità di conversione e registri specifici per piattaforma.",limits:"È l'interpretazione di un partecipante, non il consenso originale, che non è stato aperto · opinione di esperti, nessun dato quantitativo · la parte su anca (THA) è fuori dal tuo perimetro · piattaforme non nominate nell'abstract.",perte:"Verde: il consenso sulla protesi robotica tocca la tua TKA con VELYS; non dice se il VELYS sia fra le piattaforme considerate. Messaggio pratico: precisione tecnica confermata, beneficio clinico a lungo termine ancora da dimostrare. Non muove le tensioni. Cosa fare: nulla da cambiare; il documento originale resta da aprire."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Front Surg",h:"UKA mediale: piatto mobile o fisso, a 3 mesi punteggi simili su 64 pazienti",v:"Studio retrospettivo monocentrico (Shaoxing) su 64 UKA mediali (32 con piatto mobile, 32 con fisso), un solo chirurgo, controllo a 3 mesi: dolore VAS, HSS e KSS migliorano in entrambi senza differenze fra i gruppi; correzione dell'angolo femorotibiale −3,27° con il mobile contro −2,70° con il fisso (p<0,05) e guadagni di mobilità maggiori con il mobile; nessuna infezione, mobilizzazione o lussazione del piatto. Il fisso ha costo di ricovero inferiore.",ax:"Chen, Zheng, Zhu, Shan, Chen, Wan, Ye",date:"set 2026",meta:"studio retrospettivo comparativo, 64 pazienti (32 contro 32), follow-up 3 mesi",pmid:'42865442',doi:'10.3389/fsurg.2026.1746302',journal:"Frontiers in surgery",authors:"Chen H, Zheng X, Zhu S, Shan L, Chen J, Wan L, Ye F",design:"Studio retrospettivo di 64 pazienti con artrosi del compartimento mediale operati di UKA (gennaio 2022-ottobre 2024) da un unico chirurgo senior con protocollo standardizzato: 32 piatto mobile, 32 piatto fisso. Dolore VAS, HSS, KSS americano, allineamento radiografico (angolo femorotibiale e pendenza tibiale) e mobilità a 3 mesi. Letto solo l'abstract.",pop:"64 pazienti, 32 per gruppo; età, sesso e BMI non riportati nell'abstract; follow-up 3 mesi.",results:"Miglioramento di VAS, HSS e KSS in entrambi i gruppi (tutti p<0,001), nessuna differenza fra i gruppi. Correzione dell'angolo femorotibiale −3,27° contro −2,70° (p<0,05) a favore del piatto mobile, guadagni di flessione ed estensione maggiori (p<0,05). Nessuna infezione, mobilizzazione né lussazione del piatto. Deviazioni standard e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: piatto mobile e fisso danno sollievo dal dolore e miglioramento funzionale simili a breve termine; il mobile può dare più correzione di allineamento e mobilità, il fisso un vantaggio economico; la scelta dovrebbe considerare anche i costi.",limits:"Retrospettivo, 32 per gruppo, un chirurgo · follow-up di 3 mesi: nessuna informazione su sopravvivenza dell'impianto o usura · deviazioni standard e intervalli non riportati nell'abstract · il contesto dei costi è asiatico · testo completo non letto.",perte:"Verde: la UKA è una tua procedura; il tipo di piatto che usi non è nel tuo profilo, quindi nessuna annotazione di trasferibilità. A tre mesi il dato non dice nulla sulla durata dell'impianto. Non muove le tensioni. Cosa fare: nulla da cambiare."},{n:7,mono:"m-arth",dot:"gray",sec:"res",j:"Arthroscopy",h:"Allotrapianto osteocondrale: con aspirato di midollo meno reinterventi, in quattro studi",v:"Revisione sistematica di 4 studi (3 di livello III, 1 di livello I), 165 ginocchia, follow-up 5,5-18,0 mesi, su allotrapianto osteocondrale con o senza aspirato di midollo osseo: in 2 studi comparativi reinterventi 2,4% contro 21,9%; IKDC e KOOS JR senza differenze significative, MCID del KOOS JR raggiunta dall'88% contro il 55% (p=0,076); imaging discordante.",ax:"Thamrongskulsiri, Morgan, Casanova, Moews, Yanke, Cole, Chahla",date:"set 2026",meta:"revisione sistematica PRISMA, 4 studi (3 livello III, 1 livello I), 165 ginocchia",pmid:'42763432',doi:'10.1002/arj.70628',journal:"Arthroscopy : the journal of arthroscopic & related surgery : official publication of the Arthroscopy Association of North America and the International Arthroscopy Association",authors:"Thamrongskulsiri N, Morgan JT, Casanova F, Moews LD, Yanke AB, Cole BJ, Chahla J",design:"Revisione sistematica PRISMA 2020 (Rush University, Chicago) di studi clinici comparativi su allotrapianto osteocondrale (OCA) con e senza aumentazione con aspirato di midollo osseo (BMA) per difetti cartilaginei del ginocchio; screening e valutazione in doppio; rischio di bias con RoB 2.0 e MINORS. Livello di evidenza dichiarato: III. Letto solo l'abstract.",pop:"165 ginocchia in 4 studi; follow-up medio 5,5-18,0 mesi; età, sede e dimensione dei difetti non riportate nell'abstract.",results:"Reinterventi 2,4% con BMA contro 21,9% senza, in 2 studi comparativi (conteggi assoluti non riportati nell'abstract). Radiografia e RM eterogenee: un studio con integrazione più precoce e meno sclerosi a 6 mesi, due studi su RM senza differenze nell'OCA MRI Scoring System; la TC in un trial mostra più piccole cisti e una tendenza a meno cisti grandi. IKDC e KOOS JR senza differenze; MCID del KOOS JR raggiunta dall'88% contro il 55% (p=0,076). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: l'OCA con BMA si associa a reinterventi significativamente inferiori; i dati radiografici a breve termine mostrano un rimodellamento subcondrale precoce migliore, non confermato in modo costante dalla RM.",limits:"Solo due studi comparativi per l'esito principale, conteggi assoluti non riportati nell'abstract · follow-up di pochi mesi · differenza sui punteggi non significativa (p=0,076) · tre studi su quattro di livello III · testo completo non letto.",perte:"Bianco: il trapianto osteocondrale da donatore non è la tua filiera, che per la cartilagine è AMIC con Chondro-Gide e AutoCart; entra come lavoro del perimetro sulla cartilagine. Non tocca le tensioni (la tensione 5 riguarda il minced cartilage). Cosa fare: nulla da cambiare."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"SICOT J",h:"LCA con hamstring: disturbi del safeno 53,3% con due tendini contro 28,3% con uno",v:"Studio prospettico osservazionale (Kozhikode) su 120 LCA con hamstring: disturbi sensitivi nel territorio del nervo safeno nel 28,3% (17/60) con il solo semitendinoso e nel 53,3% (32/60) con semitendinoso e gracile, differenza dichiarata significativa; nella maggior parte dei casi senza ricadute sulle attività quotidiane. Valore di p e intervalli di confidenza non riportati nell'abstract.",ax:"Kunheen, Subramaniyan, Karuppal, Surendran, Cu, Govindharaaju",date:"ott 2026",meta:"studio prospettico osservazionale, 120 pazienti (60 contro 60), controllo a 6 mesi",pmid:'42878391',doi:'10.1051/sicotj/2026051',journal:"SICOT-J",authors:"Kunheen KO, Subramaniyan V, Karuppal R, Surendran S, Cu J, Govindharaaju R",design:"Studio prospettico osservazionale, aprile 2020-settembre 2023, su 120 pazienti operati di LCA artroscopica con semitendinoso solo (60) o semitendinoso più gracile (60); presenza di alterazioni sensitive nel territorio del nervo safeno a 6 mesi. Assegnazione ai gruppi e tecnica di prelievo non descritte nell'abstract. Letto solo l'abstract.",pop:"120 pazienti, 60 per gruppo; età, sesso e tecnica di prelievo non riportati nell'abstract.",results:"Alterazioni sensitive nel territorio del safeno 28,3% (17/60) con semitendinoso solo contro 53,3% (32/60) con semitendinoso più gracile; differenza dichiarata statisticamente significativa. Valore di p, rischio relativo e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il nervo safeno è più a rischio nel prelievo doppio; dove possibile evitare il doppio prelievo, con semitendinoso triplicato o quadruplicato o LCA all-inside con innesti più corti.",limits:"Gruppi non randomizzati, assegnazione non descritta · valutazione sensitiva a 6 mesi, metodo non descritto nell'abstract · valore di p non riportato nell'abstract · innesto hamstring · testo completo non letto.",perte:"Bianco: riguarda il prelievo dei tendini ischiocrurali, non il tuo retto femorale o quadricipite; il prelievo che usi ha rischi propri qui non studiati. Non tocca le tensioni. Cosa fare: nulla da cambiare."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Indian J Orthop",h:"TKA robotica image-free: taglia del femore esatta nel 92%, della tibia nel 72%",v:"Studio prospettico osservazionale (Kolkata) su 100 TKA consecutive con sistema robotico image-free: taglia femorale prevista esatta nel 92% (92/100) ed entro ±1 taglia nel 100%; tibiale esatta nel 72%, entro ±1 nel 94% ed entro ±2 nel 100%, verificate con i componenti di prova. Rispetto ai controlli storici di templating digitale, miglioramento significativo per il femore (esatta p<0,0001; ±1 p=0,003) e per la tibia (esatta p<0,0001).",ax:"Shahul Hameed, Rajput, Uwais, Basu, Setua, Goel",date:"lug 2026",meta:"studio prospettico osservazionale, 100 pazienti consecutivi, controlli storici",pmid:'42894605',doi:'10.1007/s43465-026-01879-y',journal:"Indian journal of orthopaedics",authors:"Shahul Hameed S, Rajput R, Uwais P, Basu A, Setua S, Goel AK",design:"Studio prospettico osservazionale su 100 pazienti con artrosi in fase avanzata operati di prima TKA con sistema robotico image-free (campionamento consecutivo, un'unica équipe, accesso parapatellare mediale, sega manuale); escluse revisioni e interventi precedenti. Taglie previste dal sistema verificate in cieco con componenti di prova e confrontate con controlli storici di templating digitale (chi quadro). Letto solo l'abstract.",pop:"100 pazienti consecutivi, un'équipe; età, sesso, deformità e marca del sistema non riportate nell'abstract (il nome del sistema non compare nell'abstract).",results:"Femore: taglia esatta 92% (92/100), entro ±1 taglia 100% (100/100). Tibia: esatta 72%, entro ±1 94%, entro ±2 100%. Contro il templating digitale: miglioramento significativo per femore esatto (p<0,0001) ed entro ±1 (p=0,003) e per tibia esatta (p<0,0001); entro ±1 e ±2 per la tibia senza differenza. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il sistema image-free predice con alta accuratezza la taglia femorale; la tibia è meno precisa, forse per tagli e bilanciamento dei tessuti molli; il giudizio del chirurgo resta importante.",limits:"Controlli storici, non concomitanti · un'équipe, un centro, nessun esito clinico · sistema non nominato nell'abstract, quindi non si sa se coincida con il VELYS · intervalli di confidenza non riportati nell'abstract · testo completo non letto.",perte:"Bianco: tocca la protesi robotica ma il sistema non è nominato nell'abstract; non è detto che sia il VELYS e il risultato su misura dell'impianto non è un esito clinico. Non tocca le tensioni. Cosa fare: nulla da cambiare."}];
var SUGGQ=[{"k": "kol", "n": "Daniel B. F. Saris (Mayo Clinic, Rochester, Minnesota)", "w": "Stati Uniti: coautore ricorrente nello storico, nelle ultime due settimane compare nei lavori di Mayo Clinic su MPFL, LCA con tendine quadricipitale e protesi dopo osteotomia (nome e afferenza letti nei metadati PubMed del PMID 42876992). Corrispondenza tecnica con la cartilagine (biopsie e impianto di condrociti, MACI) accanto a LCA e MPFL, cioè l'asse AMIC e AutoCart che esegui. Sostituisce Peter Balcarek (17 ottobre; nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Martedì 20 ottobre. Oggi nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo di dispositivi nuovo rispetto a ieri, nessuna linea guida o consensus nuovo che tocchi la tua pratica e nessuna ritrattazione che ti riguardi. Il lavoro del giorno è uno studio retrospettivo di Zhejiang sulla sutura del corno posteriore del menisco durante la ricostruzione del crociato anteriore: centottantasei pazienti, follow-up medio ventotto mesi. La sutura è fallita nell'undici virgola otto per cento; con i punti solo orizzontali nel diciassette virgola due, con la configurazione combinata verticale e orizzontale nel sette virgola otto, p zero virgola zero due quattro. Nel modello aggiustato la sola configurazione orizzontale ha un hazard ratio di due virgola otto quattro, intervallo di confidenza al novantacinque per cento da uno virgola tre due a sei virgola uno quattro, e il menisco mediale di due virgola quattro due. Verticale contro combinata non si distinguono. L'innesto era sempre hamstring e non il tuo, la plastica laterale non è descritta, i punti li sceglieva il chirurgo; ho letto il testo completo. Poi otto lavori. Una metanalisi di quattro studi su duecentoquarantasei pazienti non trova differenze fra tendine quadricipitale e hamstring nella ricostruzione del MPFL, senza dimensioni dell'effetto nell'abstract. Una revisione di cinque studi su milleseicentocinquantanove pazienti associa la ricostruzione tardiva del crociato a più meniscectomie e protesi, con certezza limitata. Sulla sutura del menisco, una revisione di sette studi sul coagulo di sangue o fibrina: guarigione completa fra il ventiquattro e il novantadue per cento, prove deboli. Un commento a un consenso Asia-Pacifico sulla protesi robotica: più precisione, beneficio a lungo termine incerto; è l'interpretazione di un partecipante e non il consenso originale. La protesi monocompartimentale con piatto mobile o fisso su sessantaquattro pazienti: a tre mesi punteggi simili. Poi tre lavori bianchi: l'aspirato di midollo osseo nel trapianto osteocondrale, il nervo safeno nel prelievo di due tendini della coscia e la taglia dell'impianto prevista da un sistema robotico senza immagini. Tensioni: nessuna si è mossa.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Martedì venti ottobre. Nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo nuovo, nessun consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Uno studio retrospettivo di Zhejiang sulla sutura del corno posteriore del menisco durante la ricostruzione del crociato. Centottantasei pazienti, follow-up medio ventotto mesi. La sutura è fallita nell'undici virgola otto per cento."}, {"chi": "B", "t": "E cambia in base a come sono disposti i punti?"}, {"chi": "A", "t": "Con i punti solo orizzontali il diciassette virgola due per cento, con la combinazione verticale e orizzontale il sette virgola otto. Nel modello aggiustato la sola configurazione orizzontale ha un hazard ratio di due virgola otto quattro, intervallo da uno virgola tre due a sei virgola uno quattro."}, {"chi": "B", "t": "Quindi per la tua sutura conviene cambiare?"}, {"chi": "A", "t": "No, è presto. È retrospettivo, i punti li sceglieva il chirurgo, e fra verticale e combinata non si distinguono. L'innesto era sempre hamstring, non il tuo, e la plastica laterale non è descritta."}, {"chi": "B", "t": "Gli altri lavori?"}, {"chi": "A", "t": "Una metanalisi di quattro studi sul MPFL: tendine quadricipitale e hamstring senza differenze nei punteggi, ma pochi studi retrospettivi. Una revisione di cinque studi collega la ricostruzione tardiva del crociato a più meniscectomie e protesi, con certezza limitata."}, {"chi": "B", "t": "E sulla protesi?"}, {"chi": "A", "t": "Un commento a un consenso Asia-Pacifico sul robot: più precisione tecnica, beneficio a lungo termine ancora incerto. È l'interpretazione di un partecipante, non il documento originale. Poi la monocompartimentale con piatto mobile o fisso su sessantaquattro pazienti: a tre mesi punteggi simili."}, {"chi": "B", "t": "E le tensioni?"}, {"chi": "A", "t": "Nessuna si è mossa."}];
